// Product images live in the public Supabase "product-images" bucket.
// Each upload is stored as resized WebP files: <storage_path>-480.webp, -960.webp, -1440.webp
// (generated by the server in phase 4).
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL
export const IMAGE_WIDTHS = [480, 960, 1440]

export function imageUrl(storagePath, width = 960) {
  if (/^https?:\/\//.test(storagePath)) return storagePath
  return `${SUPABASE_URL}/storage/v1/object/public/product-images/${storagePath}-${width}.webp`
}

export function imageSrcSet(storagePath) {
  if (/^https?:\/\//.test(storagePath)) return undefined
  return IMAGE_WIDTHS.map((w) => `${imageUrl(storagePath, w)} ${w}w`).join(', ')
}
